/**
 * Agent emission (M3, plan §4.3): `agentToTf` consumes the discovered
 * `DeployableEntity` (the `agent` def() payload) and emits
 * `elementum_agent` + one tool resource per implemented tool (the tool pass
 * delegates to `entities/agent-tool/to-tf.ts`) + one `elementum_agent_a2a_skill`
 * per a2aSkills entry (delegates to `entities/agent-a2a-skill/to-tf.ts`,
 * issue #68).
 *
 * The dialect is ei's ACTUAL export (docs/design/m3-agent-dialect.md):
 * app_id as the owning app's resource ref, the connector as a
 * `data.elementum_ai_provider_connector` ref, agent-prefixed tool labels.
 * `skillAccess` emits `skill_access_config` (confirmed live against the
 * provider's `elementum_agent` schema). `startingActions` emit
 * `starting_actions` (issue #760). Authoring knobs the terraform dialect
 * still doesn't carry (temperature, reasoningEffort, …) degrade through
 * `diagnostics` — reported, never silent (plan §4.3).
 */
import { type OrgRefLookup, type WorkspaceAspect } from "../../engine/build/context.js";
import { type DeployableEntity } from "../../engine/entity.js";
import { type TfBlock } from "../../engine/tf/index.js";
import type { AppServiceAccount } from "../service-account/build.js";
export interface AgentToTfContext {
    /** The owning app's refName (self-target detection) and tfLabel (namespace). */
    readonly appRefName: string;
    readonly appTfLabel: string;
    readonly orgRefs: OrgRefLookup;
    readonly workspaceAspects?: ReadonlyMap<string, WorkspaceAspect>;
    /** Inline service accounts authored on the owning app, keyed by stable bag key. */
    readonly serviceAccounts?: Readonly<Record<string, AppServiceAccount>>;
    /** Degradations land here — reported by the caller, never silent. */
    readonly diagnostics: string[];
    /**
     * Every agent entity discovered for this app (self included) — forwarded
     * by build.ts, unordered. Used to replicate ei's cross-agent a2a-skill
     * label disambiguation (see {@link computeA2ASkillLabelSuffixes}). Absent
     * in contexts that don't supply it (e.g. most unit tests): every a2a
     * skill then gets the bare label, matching the pre-#294 single-agent
     * behavior.
     */
    readonly siblingEntities?: readonly DeployableEntity[];
    readonly activeAutomationRefNames?: ReadonlySet<string>;
}
export interface AgentToTfResult {
    readonly blocks: readonly TfBlock[];
    /** The agent's terraform address. */
    readonly address: string;
}
/**
 * Mirrors ei's cross-agent a2a-skill-name disambiguation
 * (`cmd/elementum/export/imports.go`'s `a2aNames` counting map over
 * `app.AllAgents()`): a same-app, same-named a2a skill on two different
 * agents is not a collision on the platform — ei's exporter gives the
 * first occurrence of a sanitized name the bare label, each later
 * occurrence `_1`, `_2`, …
 *
 * Ascending-by-agent-NAME confirmed live 2026-08-18 against real committed
 * state on a deployed app (two identically-named a2a skills added via the
 * platform UI to two different agents): "Default agent 2" landed at the
 * bare label, "test agent" at `_1` — `D` < `t`, matching the assumed sort.
 * A weaker signal than #310's skill-tool capture (that one deliberately
 * reordered 3 skills' creation vs. name to rule out creation-order as an
 * alternative explanation; this one only has 2 agents, so an
 * agent-creation-order coincidence can't be fully excluded) — but real
 * evidence from `ei`'s own exporter/import-address generation, not a
 * guess. If a future capture contradicts it, only this function's sort
 * needs to change — the suffix-assignment mechanics stay the same.
 * Ordering of a2a skills WITHIN one agent is still assumed to be authored
 * array order, unconfirmed live either way.
 *
 * Returns suffixes ("" for the first occurrence, "_1", "_2", … after)
 * keyed by `${agentRefName}#${sanitizedName}` — NOT by skill index. Every
 * entry on the SAME agent sharing a sanitized name maps to the identical
 * suffix (only a name's first appearance on a given agent advances the
 * cross-agent counter), so an intra-agent duplicate still collides on one
 * address instead of silently acquiring a distinct label — that's a real
 * authoring mistake (two skills with the identical name on ONE agent),
 * still caught and dropped by `agentToTf`'s existing
 * `seenA2ASkillAddresses` check. Only DIFFERENT agents reusing a name are
 * the #294 case this disambiguates.
 */
export declare function computeA2ASkillLabelSuffixes(siblingAgents: readonly DeployableEntity[]): ReadonlyMap<string, string>;
/** `elementum_agent` + one tool resource per implemented tool, in ei's dialect. */
export declare function agentToTf(entity: DeployableEntity, ctx: AgentToTfContext): AgentToTfResult;
